    <script>
        /* ===========================================
           SLIDE PRESENTATION CONTROLLER
           =========================================== */
        class SlidePresentation {
            constructor() {
                this.slides = document.querySelectorAll('.slide');
                this.currentSlide = 0;
                this.progressBar = document.querySelector('.progress-bar');

                this.setupNavDots();
                this.setupIntersectionObserver();
                this.setupKeyboardNav();
                this.setupTouchNav();
                this.updateUI();
            }

            setupNavDots() {
                const navContainer = document.querySelector('.nav-dots');
                if(!navContainer) return;

                this.slides.forEach((_, index) => {
                    const dot = document.createElement('div');
                    dot.classList.add('dot');
                    dot.addEventListener('click', () => this.goToSlide(index));
                    navContainer.appendChild(dot);
                });
                this.dots = document.querySelectorAll('.dot');
            }

            setupIntersectionObserver() {
                const options = { root: null, rootMargin: '0px', threshold: 0.5 };

                const observer = new IntersectionObserver((entries) => {
                    entries.forEach(entry => {
                        if (entry.isIntersecting) {
                            entry.target.classList.add('visible');
                            // Update current slide index based on intersection
                            const index = Array.from(this.slides).indexOf(entry.target);
                            if(index !== -1) {
                                this.currentSlide = index;
                                this.updateUI();
                            }
                        }
                    });
                }, options);

                this.slides.forEach(slide => observer.observe(slide));
            }

            goToSlide(index) {
                if (index >= 0 && index < this.slides.length) {
                    this.currentSlide = index;
                    this.slides[this.currentSlide].scrollIntoView({ behavior: 'smooth' });
                    this.updateUI();
                }
            }

            setupKeyboardNav() {
                document.addEventListener('keydown', (e) => {
                    if (e.key === 'ArrowRight' || e.key === 'ArrowDown' || e.key === 'PageDown' || e.key === ' ') {
                        e.preventDefault();
                        this.goToSlide(this.currentSlide + 1);
                    } else if (e.key === 'ArrowLeft' || e.key === 'ArrowUp' || e.key === 'PageUp') {
                        e.preventDefault();
                        this.goToSlide(this.currentSlide - 1);
                    }
                });
            }

            setupTouchNav() {
                let startY = 0;
                let startX = 0;

                document.addEventListener('touchstart', e => {
                    startY = e.touches[0].clientY;
                    startX = e.touches[0].clientX;
                }, {passive: true});

                document.addEventListener('touchend', e => {
                    const endY = e.changedTouches[0].clientY;
                    const endX = e.changedTouches[0].clientX;
                    const diffY = startY - endY;
                    const diffX = startX - endX;

                    if (Math.abs(diffY) > 50 || Math.abs(diffX) > 50) {
                        if (Math.abs(diffX) > Math.abs(diffY)) {
                            // Horizontal swipe
                            if (diffX > 0) this.goToSlide(this.currentSlide + 1);
                            else this.goToSlide(this.currentSlide - 1);
                        }
                    }
                }, {passive: true});
            }

            updateUI() {
                // Update dots
                if(this.dots) {
                    this.dots.forEach((dot, index) => {
                        dot.classList.toggle('active', index === this.currentSlide);
                    });
                }

                // Update progress bar
                if(this.progressBar && this.slides.length > 1) {
                    const progress = (this.currentSlide / (this.slides.length - 1)) * 100;
                    this.progressBar.style.width = `${progress}%`;
                }
            }
        }

        document.addEventListener('DOMContentLoaded', () => {
            new SlidePresentation();
        });
    </script>
